\label{cor:2cplt-sur}
Let $(X,\Delta)$ be a pair with standard coefficients and let $\Gamma \ge \Delta$ be a divisor with coefficients in $\{0,\frac{1}{2},1\}$.
Then, there is a surjective group homomorphism $\pi_1^{\rm orb}(X,\Gamma)\twoheadrightarrow \pi_1^{\rm orb}(X,\Delta)$.

The following proper morphisms are flat in codimension zero and one in the source:
\begin{enumerate}
    \item a finite surjective morphism $p:X'\to X$, with $X'$ and $X$ normal projective varieties;
    \item an equidimensional fibration $f:X\to B$,  with $X$ and $B$ normal projective varieties.
\end{enumerate}

\label{prop:galois1}
    Let $p:(X',\Delta') \to (X,\Delta)$ be a compatible morphism between two pairs. If it also is a finite Galois cover, then we have an exact sequence of groups
    $$1\longrightarrow \pi_1^{\rm orb}(X',\Delta') \overset{p_{\bullet}}{\longrightarrow} \pi_1^{\rm orb}(X,\Delta) \longrightarrow {\rm Gal}(p) \longrightarrow 1.$$

\label{prop:galois2}
    Let $(X,\Delta)$ be a pair. Let $H$ be a normal subgroup of finite index in $\pi_1^{\rm orb}(X,\Delta)$. Then there exist a pair $(X_H,\Delta_H)$, and a finite Galois cover $p_H:X_H\to X$ compatible with the two pairs, such that the subgroups $H$ and
    ${p_H}_{\bullet}[\pi_1^{\rm orb}(X_H,\Delta_H)]$ coincide in $\pi_1^{\rm orb}(X,\Delta)$.

\label{lem:fun-under-surj-smooth}
Let $X$ and $Y$ be normal projective surfaces, and let $\varphi\colon X\rightarrow Y$ be a proper birational morphism. 
If the image of the reduced exceptional divisor $E$ of $\varphi$ lies in $Y_{\rm reg}$, then the fundamental groups $\pi_1(X_{\rm reg})$ and $\pi_1(Y_{\rm reg})$ are isomorphic.

\label{def:mult-divisor}
    Let $(X,\Delta)$ be a pair, and $f: X\to C$ be an equidimensional fibration. Denote by $\Delta_{\rm vert}$ the $f$-vertical part of the divisor $\Delta$. We say that $f$ is an {\it equimultiple fibration} if there exists a divisor $\Delta_C$ on $C$ with standard coefficients such that $f$ is compatible with the pairs $(X,{\Delta_{\mathrm{vert}}}^{\rm st})$ and $(C,\Delta_C)$.
    The (unique) such divisor $\Delta_C$ on $C$ is called the divisor {\it induced by $f$}.

\label{rem:mfscompatible}
   If $f:(X,\Delta)\to (C,\Delta_C)$ is an equimultiple fibration from a surface to a curve, and the pair $(X,\Delta)$ is 
    \begin{itemize}
        \item log canonical Calabi-Yau, then $(C,\Delta_C)$ is a log canonical Fano or log canonical Calabi--Yau pair;
        \item log canonical Fano, then $(C,\Delta_C)$ is a log canonical Fano pair.
    \end{itemize}

\label{lem:nori}
Let $f:(X,\Delta)\to (C,\Delta_C)$ be an equimultiple fibration. Let $i:F\hookrightarrow X$ be the inclusion of a general fiber of $f$. Then the following sequence is exact:
$$\pi_1^{\rm orb}(F,\Delta|_F)\overset{i_{\bullet}}{\longrightarrow} \pi_1^{\rm orb}(X,\Delta)\overset{f_{\bullet}}{\longrightarrow} \pi_1^{\rm orb}(C,\Delta_C)\to 1.$$

The {\em regional fundamental group} 
of a pair $(X,\Delta)$ at a closed point $x\in X$ is
denoted by $\pi_1^{\rm reg}(X,\Delta;x)$, and is defined as the inverse limit of all groups $\pi_1^{\rm orb}(U,\Delta|_U)$, where $U$ ranges over all analytic neighborhoods of $x$ in $X$.

