\label{lem:ab-group}
Let $G$ be a finitely generated abelian group, and let $r\in\mathbb{N}$.
If there is a decreasing sequence of normal subgroups $(H_n)_{n\in \mathbb{N}}$ with trivial intersection such that each quotient $G/H_n$ has rank at most $r$, then $G$ has rank at most $r$.

\label{rem:dual-complex}
    Let $(X,\Delta)$ be a log canonical Calabi-Yau surface pair. Its dual complex clearly has dimension at most $1$. Therefore, by \cite[Theorem 1.6]{FS20}, the dual complex $\mathcal{D}(X,\Delta)$ is piecewise linearly homeomorphic to one of the following manifolds with boundary:
    $$\emptyset,\{0\},\{0,1\},[0,1],S^1.$$

Let $(X,\Delta)$ be an lc pair. Let $N\ge 1$ be an integer. We say that a $\mathbb{Q}$-divisor $\Gamma\ge \Delta$ is an {\it $N$-complement} of $(X,\Delta)$ if:
\begin{itemize}
    \item $(X,\Gamma)$ is an lc pair,
    \item $N\Gamma$ is an integral Weil divisor, and $N(K_X+\Gamma)\sim 0$. 
\end{itemize}

\label{lem:coreg-vs-complementCY}
Let $(X,\Delta)$ be an lc Calabi--Yau pair with standard coefficients.
\begin{itemize}
\item If ${\rm coreg}(X,\Delta)=0$, then
$(X,\Delta)$ is a $2$-complement.
\item If ${\rm coreg}(X,\Delta)=1$, then $(X,\Delta)$ is an $N$-complement for some $N\in \{1,2,3,4,6\}$.
\end{itemize}

\label{lem:coreg-vs-complementFano}
Let $(X,\Delta)$ be an lc Fano pair with standard coefficients.
\begin{itemize}
\item If ${\rm coreg}(X,\Delta)=0$, then
$(X,\Delta)$ admits a $2$-complement of coregularity zero.
\item If ${\rm coreg}(X,\Delta)=1$, then $(X,\Delta)$ admits an $N$-complement of coregularity one, for some $N\in \{1,2,3,4,6\}$.
\end{itemize}

Let $(X,\Delta)$ be a klt Calabi--Yau surface pair with standard coefficients. By~\cite[Lemma~2.7]{CGG23}, there exists a Zariski open set $U\subset X$ such that $\operatorname{codim}_{X\setminus U}(X)\geq 3$ and $(U,\Delta|_{U})$ is an orbifold. Since $X$ is a surface, we have $U=X$ and thus~\cite[Theorem~4.2]{CC14} provides the following exact sequence
 \begin{center}
     $1\rightarrow A_0\rightarrow \pi_1^{\rm orb}(X,\Delta)\rightarrow G_0\rightarrow 1$,
 \end{center}
 where $A_0$ is an abelian group of rank at most $4$ and $G_0$ is a finite group.

By Proposition~\ref{prop:galois2}, there is a finite orbifold cover $\pi:(X_0,\Delta_0)\rightarrow (X, \Delta)$ with Galois group $G_0$ and with an equality of subgroups $\pi_{\bullet}\pi_1^{\rm orb}(X_0,\Delta_0)=A_0$. 
By the Riemann--Hurwitz formula and \cite[Proposition 5.20]{KM98}, the pair $(X_0,\Delta_0)$ is klt and Calabi--Yau.

By the non-vanishing result \cite[V.4.9 Corollary]{Nak04}, there is a positive integer $M$ such that $M(K_{X_0}+\Delta_0)\sim 0$, hence the index one cover of $(X_0,\Delta_0)$ given by Lemma \ref{lem:index-one-cover} is a klt Gorenstein surface $X_1$ with $K_{X_1}\sim 0$. In particular, it has canonical singularities. Take the minimal resolution of singularities $r:Y\rightarrow X_1$. Then $Y$ is a K3 surface or an abelian surface.



By uniqueness of the index one cover, the composition of finite covers $(X_1,0)\rightarrow (X,\Delta)$ remains a compatible Galois cover. We denote its Galois group by $G_1$. Then we have a short exact sequence
\begin{center}
    $1\rightarrow \mathbb{Z}/M\mathbb{Z}\rightarrow G_1\rightarrow G_0\rightarrow 1$.
\end{center}
By uniqueness of the minimal resolution, the action of $G_1$ on $X_1$ lifts to an action by automorphisms on $Y$.

If $Y$ is an abelian surface, then it contains no rational curves, thus $Y\simeq X_1$.
Let $T\triangleleft G_1$ be the normal subgroup of $G_1$ acting on $X_1$ by translations, and consider the abelian surface $S:=X_1/T$ with the naturally induced compatible Galois cover $(S,0)\rightarrow (X,\Delta)$ of Galois group isomorphic to $Q:=G_1/T$. The Galois action of $Q$ on $S$ fixes the origin of $S$, hence $Q$ is contained in the group of Lie group automorphisms of $S$. Now \cite[Lemma~3.2 and 3.3]{Fujiki88} imply that $|Q|\leq 96$. We reach the following short exact sequence
\begin{center}
    $1\rightarrow \mathbb{Z}^4 \rightarrow \pi_1^{\rm orb}(X,\Delta)\rightarrow Q\rightarrow 1$.
\end{center}

When $Y$ is a $K3$ surface, \cite[Theorem~1]{Kondo99} implies that $|G_0|\le |G_1|\leq 3840$. In that case, note that $\pi_1^{\rm orb}(X,\Delta)$ is in fact isomorphic to $G_1$.

