\label{def:trichotomy}
    Let $(C,\Delta)$ be a Fano or Calabi--Yau curve pair. We say that $(C,\Delta)$ is of:
    \begin{enumerate}
    \item {\it elliptic type} if $(C,\Delta^{\rm st})$ is a klt Calabi--Yau pair;
    \item {\it toric type} if there is a non-klt $2$-complement $(C,\Gamma)$ of $(C,\Delta^{\rm st})$;
    \item {\it sporadic type} if $(C,\Delta^{\rm st})$ is of the form $$\left(\mathbb{P}^1,\frac{1}{2}\{0\}+\frac{2}{3}\{1\}+\frac{n-1}{n}\{\infty\}\right),$$
    for some $n\in\{3,4,5\}$.
    \end{enumerate}

\label{lem:toricpair}
    Let $(C,\Delta)$ be a pair of toric type. Then $\pi_1^{\rm orb}(C,\Delta)$ is isomorphic to $(\mathbb{Z}/2\mathbb{Z})^2$, or it admits a cyclic characteristic subgroup of index at most $2$. 
    Moreover, the group is infinite if and only if the pair is Calabi--Yau.

Let $X$ be a normal projective surface. We say that it admits a {\it Mori fiber space onto a curve} if the following requirements hold
\begin{itemize}
    \item $X$ is $\mathbb{Q}$-factorial with lc singularities;
    \item there is a fibration $f:X\to C$, where $C$ is a smooth curve;
    \item the general fibre of $f$ is isomorphic to $\mathbb{P}^1$, and $\rho(X)=2$.
\end{itemize}

\label{lem:sarkisovlink}
Let $(X,\Delta)$ be an lc Calabi-Yau pair where $X$ is a surface and a Mori fiber space onto a curve $C$. Then there exists a birational modification $(X',\Delta')$ of $(X,\Delta)$ relative to the base curve $C$ such that
\begin{itemize}
    \item All log canonical centers of $(X',\Delta')$ are contained in $\lfloor\Delta'\rfloor$;
    \item The fibration $f':X'\to C$ induced by $f:X\to C$ remains a Mori fiber space;
    \item The pair $(X',\Delta')$ remains an lc Calabi--Yau pair;
    \item We have a surjective homomorphism $\pi_1^{\rm orb}(X',\Delta')\twoheadrightarrow\pi_1^{\rm orb}(X,\Delta)$.
\end{itemize}

